/*
 * ASK WHEN THE PAGE SAYS WHOSE LESSON AND WHICH STEP (TASK-L190). Both come from
 * the page's query (?learner=&concept=); with either missing nothing is asked,
 * and the page says there is nothing to preview rather than guessing one.
 */
const learner = String(Inputs.learnerId || '');
const concept = String(Inputs.conceptId || '');
if (!learner || !concept) return;
Outputs.learnerId = learner;
Outputs.conceptId = concept;
Outputs.which = Inputs.which === 'published' ? 'published' : 'draft';
Outputs.ask();

/*
 * A REFUSAL IS NO LESSON (TASK-L171). Signed out, the App gate sends the page
 * to sign-in before this could matter; if the call fails anyway, the page gets
 * the same empty answer a lesson not written yet gets, not a spinner.
 */
Outputs.items = [];

function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
/*
 * Data/Lesson's split (le_split), plus the three things a preview must say that a
 * learner's own page never needs: whether this is the DRAFT or what they see,
 * whose lesson it is, and which step. Empty in, every part emptied and found false.
 */
const rows = plain(Inputs.items) || [];
const lesson = rows[0];
if (!lesson) {
  Outputs.title = '';
  Outputs.hook = '';
  Outputs.landing = '';
  Outputs.conceptId = '';
  Outputs.steps = [];
  Outputs.sections = [];
  Outputs.found = false;
  Outputs.which = '';
  Outputs.name = '';
  Outputs.conceptTitle = '';
  Outputs.live = false;
  Outputs.loaded();
  return;
}
Outputs.title = lesson.title || '';
Outputs.hook = lesson.hook || '';
Outputs.landing = lesson.landing || '';
Outputs.conceptId = lesson.conceptId || '';
Outputs.steps = lesson.steps || [];
Outputs.sections = lesson.sections || [];
Outputs.found = true;
Outputs.which = lesson.which || 'draft';
Outputs.name = lesson.name || '';
Outputs.conceptTitle = lesson.conceptTitle || '';
Outputs.live = lesson.live === true;
Outputs.loaded();
